'use strict';

function normalizePath(value) {
  return String(value || '').replace(/\\/g, '/');
}

function findBraceRange(pattern) {
  let escaped = false;
  for (let i = 0; i < pattern.length; i += 1) {
    const char = pattern[i];
    if (escaped) {
      escaped = false;
      continue;
    }
    if (char === '\\') {
      escaped = true;
      continue;
    }
    if (char === '{') {
      let depth = 1;
      let innerEscaped = false;
      for (let j = i + 1; j < pattern.length; j += 1) {
        const nextChar = pattern[j];
        if (innerEscaped) {
          innerEscaped = false;
          continue;
        }
        if (nextChar === '\\') {
          innerEscaped = true;
          continue;
        }
        if (nextChar === '{') {
          depth += 1;
        } else if (nextChar === '}') {
          depth -= 1;
          if (depth === 0) {
            return { start: i, end: j };
          }
        }
      }
      return null;
    }
  }
  return null;
}

function splitBraceParts(body) {
  const parts = [];
  let current = '';
  let depth = 0;
  let escaped = false;

  for (let i = 0; i < body.length; i += 1) {
    const char = body[i];
    if (escaped) {
      current += char;
      escaped = false;
      continue;
    }
    if (char === '\\') {
      current += char;
      escaped = true;
      continue;
    }
    if (char === '{') {
      depth += 1;
      current += char;
      continue;
    }
    if (char === '}') {
      depth = Math.max(0, depth - 1);
      current += char;
      continue;
    }
    if (char === ',' && depth === 0) {
      parts.push(current);
      current = '';
      continue;
    }
    current += char;
  }

  parts.push(current);
  return parts;
}

function expandBraces(pattern) {
  const range = findBraceRange(pattern);
  if (!range) {
    return [pattern];
  }

  const before = pattern.slice(0, range.start);
  const body = pattern.slice(range.start + 1, range.end);
  const after = pattern.slice(range.end + 1);
  const parts = splitBraceParts(body);
  const expanded = [];

  for (const part of parts) {
    for (const tail of expandBraces(after)) {
      expanded.push(`${before}${part}${tail}`);
    }
  }

  return expanded;
}

function escapeRegex(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function globToRegex(pattern) {
  let regex = '';
  for (let i = 0; i < pattern.length; i += 1) {
    const char = pattern[i];

    if (char === '\\' && i + 1 < pattern.length) {
      regex += escapeRegex(pattern[i + 1]);
      i += 1;
      continue;
    }

    if (char === '*') {
      const next = pattern[i + 1];
      if (next === '*') {
        const after = pattern[i + 2];
        if (after === '/') {
          regex += '(?:.*/)?';
          i += 2;
        } else {
          regex += '.*';
          i += 1;
        }
      } else {
        regex += '[^/]*';
      }
      continue;
    }

    if (char === '?') {
      regex += '[^/]';
      continue;
    }

    if (char === '[') {
      let j = i + 1;
      let classBody = '';
      let closed = false;

      if (pattern[j] === '!') {
        classBody += '^';
        j += 1;
      }

      for (; j < pattern.length; j += 1) {
        const inner = pattern[j];
        if (inner === '\\' && j + 1 < pattern.length) {
          classBody += `\\${pattern[j + 1]}`;
          j += 1;
          continue;
        }
        if (inner === ']') {
          closed = true;
          break;
        }
        classBody += inner;
      }

      if (closed) {
        regex += `[${classBody}]`;
        i = j;
        continue;
      }

      regex += '\\[';
      continue;
    }

    regex += escapeRegex(char);
  }

  return regex;
}

function minimatch(path, pattern, options = {}) {
  const normalizedPath = normalizePath(path);
  const patterns = expandBraces(pattern);
  const flags = options.nocase ? 'i' : '';

  for (const entry of patterns) {
    const regex = new RegExp(`^${globToRegex(entry)}$`, flags);
    if (regex.test(normalizedPath)) {
      return true;
    }
  }
  return false;
}

module.exports = {
  minimatch,
};
